// Embeds the dive computer fixtures into a Dart file, because integration
// tests on the phone cannot read files from the PC (tasks.md T4.5).
//
//   dart run tool/embed_fixtures.dart
//
// test/tool/embed_fixtures_test.dart fails when the output is out of date.

import 'dart:convert';
import 'dart:io';

const fixtureDir = 'test/fixtures/divecomputer/eon_core';
const outputPath = 'integration_test/eon_core_fixtures.g.dart';

void main() {
  File(outputPath)
    ..createSync(recursive: true)
    ..writeAsStringSync(generate());
  stdout.writeln('Wrote $outputPath');
}

/// The generated file for the fixtures currently in [fixtureDir].
String generate() {
  final bins =
      Directory(fixtureDir)
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.bin'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));

  final out = StringBuffer()
    ..writeln('// GENERATED by tool/embed_fixtures.dart from $fixtureDir.')
    ..writeln('// Do not edit; run `dart run tool/embed_fixtures.dart`.')
    ..writeln()
    ..writeln('class EmbeddedFixture {')
    ..writeln(
      '  const EmbeddedFixture(this.name, this.expectedJson, '
      'this.rawBase64);',
    )
    ..writeln()
    ..writeln('  final String name;')
    ..writeln('  final String expectedJson;')
    ..writeln('  final String rawBase64;')
    ..writeln('}')
    ..writeln()
    ..writeln('const eonCoreFixtures = [');
  for (final bin in bins) {
    final name = bin.uri.pathSegments.last.replaceFirst('.bin', '');
    final expected = File(bin.path.replaceFirst('.bin', '.expected.json'))
        .readAsStringSync()
        .trim();
    out
      ..writeln('  EmbeddedFixture(')
      ..writeln("    '$name',")
      ..writeln("    r'''$expected''',")
      ..writeln("    '${base64Encode(bin.readAsBytesSync())}',")
      ..writeln('  ),');
  }
  out.writeln('];');
  return out.toString();
}
